/**
 * The membership a session, an assignment or a notification may actually rely
 * on. `findMember` also returns a removed member's row — its `archivedAt`
 * says the membership ended, but its `status` is left untouched as a record of
 * what it was — so every caller that means "are they still here" must go
 * through this instead of re-deriving the check.
 */
export async function findActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await findMember(orgId, userId);
  return member && member.status === "active" && isLive(member) ? member : null;
}

