/**
 * A project's lead can only be a current member of the organization — a
 * former member, or anyone else who never belonged, is refused outright
 * rather than silently ignored.
 */
async function assertValidLead(
  orgId: OrgId,
  leadId: UserId | null,
): Promise<void> {
  if (leadId === null) return;

  const member = await memberRepo.findActiveMember(orgId, leadId);
  if (!member) {
    throw new Error(
      "A project's lead must be a current member of the organization",
    );
  }
}

